build/testDts.js — add the two new helper functions immediately after `runTests()` and before `getTypeScriptVersions()` (currently line 63):
```js
function isSupportedTSConfigModuleField(ts, moduleName) {
    if (moduleName === undefined) {
        return true;
    }
    const map = {
        'none': 'None', 'commonjs': 'CommonJS', 'amd': 'AMD', 'umd': 'UMD',
        'system': 'System', 'es6': 'ES2015', 'es2015': 'ES2015', 'es2020': 'ES2020',
        'es2022': 'ES2022', 'esnext': 'ESNext', 'node16': 'Node16', 'nodenext': 'NodeNext',
    };
    const enumKey = map[moduleName.toLowerCase()];
    return enumKey != null && ts.ModuleKind[enumKey] != null;
}

function isSupportedTSConfigModuleResolutionField(ts, tsVersion, moduleResolutionName) {
    if (moduleResolutionName === undefined) {
        return true;
    }
    const map = {
        'classic': 'Classic',
        'node': 'NodeJs',
        // 'nodejs': 'NodeJs', // Older TS do not support value "nodejs".
        'node10': 'Node10', 'node16': 'Node16', 'nodenext': 'NodeNext', 'bundler': 'Bundler',
    };
    const enumKey = map[moduleResolutionName.toLowerCase()];

    if (enumKey === 'NodeNext') {
        // "NodeNext" is unstable before TSv4.7, and error will be thrown.
        if (semver.lt(tsVersion + '.0', '4.7.0')) {
            return false;
        }
    }

    return enumKey != null && ts.ModuleResolutionKind[enumKey] != null;
}
```
`semver` is already required at line 25 and `MIN_VERSION = '3.5.0'` (line 27) stays unchanged.

